import CoreGraphics
import Foundation
import ImageIO

/// The complete 66-indicator EP-40 display artwork already embedded in the
/// shipped USDZ. Keeping a copy here lets runtime frames retain every indicator
/// while selectively dimming and relighting them.
enum EP40DisplayArtwork {
    static func makeBaseImage() -> CGImage? {
        let compact = pngBase64.filter { !$0.isWhitespace }
        guard let data = Data(base64Encoded: compact),
              let source = CGImageSourceCreateWithData(data as CFData, nil)
        else { return nil }
        return CGImageSourceCreateImageAtIndex(source, 0, nil)
    }

    private static let pngBase64 = """

"""
}

